package set.starlev.injections.mixin.sounds;

import net.minecraft.client.resources.sounds.SoundInstance;
import net.minecraft.client.sounds.SoundEngine;
import net.minecraft.client.sounds.SoundManager;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundSource;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;
import set.starlev.StarredHeltix;

@Mixin(SoundEngine.class)
public class SoundEngineMixin {

    @Inject(method = "play", at = @At("HEAD"), cancellable = true)
    private void onPlay(SoundInstance sound, CallbackInfoReturnable<SoundEngine.PlayResult> cir) {
        if (!StarredHeltix.feature.music.disableExplosionSounds) return;

        SoundSource source = sound.getSource();
        if (source != SoundSource.BLOCKS && source != SoundSource.HOSTILE && source != SoundSource.NEUTRAL && source != SoundSource.PLAYERS) return;

        ResourceLocation location = sound.getLocation();
        String path = location.getPath();

        if (path.contains("explode") || path.contains("blast") || path.contains("tnt")) {
            cir.setReturnValue(SoundEngine.PlayResult.NOT_STARTED);
        }
    }
}

